"""Prepare the independently pictured, explicitly uncovered Bis stand."""
import copy,hashlib,json,math
from pathlib import Path
from shapely.geometry import Polygon
from shapely.ops import unary_union,nearest_points
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((ROOT/p).read_text('utf8'))
digest=lambda v:hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':')).encode()).hexdigest()
target=ROOT/'src/circuits/europe/spa-gold7-bis-2026.json';assert not target.exists(),'Preserve reviewed Bis record'
review=read('src/circuits/season-review/spa-la-source-2026.json');data=read('src/circuits/generated/spa.json');m=read('artifacts/goal-review/spa-native/road.json')
assert hashlib.sha256((ROOT/'src/circuits/generated/spa.json').read_bytes()).hexdigest()==m['generatedSha256']
raw=(ROOT/'research/season-review/spa/gold7-bis-20260114.html').read_bytes();text=raw.decode('utf8')
assert all(v in text for v in ['2026-07-16','2026-07-19','BELGIAN GRAND PRIX 2026','data-ticket-name="Gold 7 Bis : Source (Weekend) - Uncovered"'])
page=(ROOT/'research/season-review/spa/gold7-bis-page-20261028.html').read_bytes();photo=(ROOT/'research/season-review/spa/gold7-bis-360.jpg').read_bytes()
photo_url='https://www.spagrandprix.com/assets/bacd92b0-ddae-4bc6-af8f-674fa1a0f576/360-gold-7-bis.jpg'
assert photo_url.removeprefix('https://www.spagrandprix.com') in page.decode('utf8')
native=next(c for c in review['nativeCandidates'] if c['way']==1366085154);boundary=native['boundary'];front=[boundary[i] for i in [2,3]]
o=m['origin'];f=[111320*math.cos(math.radians(o[1]))*m['calibration'],-111320*m['calibration']];xy=lambda p:[(p[i]-o[i])*f[i] for i in range(2)]
polygon=Polygon([xy(p) for p in boundary]);road=unary_union([Polygon(t) for t in m['triangles']]);assert polygon.intersection(road).area<1e-6
conflicts=[z['zoneId'] for z in data['spectatorZones'] if polygon.intersection(Polygon([xy(p) for p in z['boundary']])).area>1e-6];assert not conflicts,conflicts
facilities=read('src/circuits/facilities/spa.json');fm=read('artifacts/goal-review/spa-native/facilities.json');assert fm['generatedSha256']==m['generatedSha256'];assert fm['facilitiesSha256']==hashlib.sha256((ROOT/'src/circuits/facilities/spa.json').read_bytes()).hexdigest()
pit=unary_union([Polygon(t) for t in fm['pitTriangles']]);buildings=unary_union([Polygon([xy(p) for p in b['boundary']]) for b in facilities['buildings']]);assert polygon.intersection(pit).area<1e-6 and polygon.intersection(buildings).area<1e-6
reference=nearest_points(polygon.centroid,road)[1];opening=dict(url='https://web.archive.org/web/20260114011554id_/https://www.spagrandprix.com/en/tickets-gold-7-bis',checkedAt='2026-10-28',method='published',confidence='high',notes='Dated organizer2026 page explicitly names Gold7 Bis Source Weekend as Uncovered. Hospitality package wording is not used to override this primary product description.')
profile=dict(url=photo_url,checkedAt='2026-10-28',method='estimated',confidence='low',notes='Official Bis panorama places the uncovered bank between the two covered stands.15 rows,6.72m rise,2.2m base and1m front railing are simplified estimates, not a structural or seat survey. Native building plan approximates the seating footprint; stairs/aisles are simplified.')
layer=read('src/circuits/barriers/spa-gold7.json')
zone=dict(zoneId='gold-7-bis-source',name='Gold 7 Bis · Source',kind='grandstand',availability='available',boundary=boundary,surface=dict(baseHeight=2.2,rise=6.72,depth=polygon.area/max(1,math.dist(xy(front[0]),xy(front[1]))),eyeHeight=1.2),surfaces=[dict(surfaceId='gold-7-bis-source-1',boundary=boundary,baseHeight=2.2,rise=6.72,rows=15,eyeHeight=1.2,rowFrontEdge={'coordinates':front},groundReference=[sum(p[i] for p in front)/2 for i in range(2)],frontReference=[o[i]+reference.coords[0][i]/f[i] for i in range(2)],fenceMode='authored',frontRailing={'heightMetres':1.0,'source':profile})],source=dict(url='https://www.openstreetmap.org/way/1366085154',checkedAt='2026-10-28',method='estimated',confidence='medium',notes='Independently labelled official Bis panorama shows this uncovered bank between Gold7 and Gold8 roofs; cross-checked against SPW2023. Physical association, not surveyed2026 ticket geography.'),openingSource=opening,surfaceSource=profile,requiredBarrierIds=[b['id'] for b in layer['barriers']],geometryReview=dict(checkedAt='2026-10-28',issues=[],method='Independent Bis panorama and explicit2026 uncovered product; native plan/front edge; zero current road, pit, building or other-zone plane overlap. Heights estimated.'))
record=dict(circuitId='spa',season=2026,nativeStandWay=1366085154,oldZone=None,zone=zone,barrierLayer=layer,covered=False,identityAccepted=True,runtimeApplied=False,sceneAcceptance={'accepted':False},geometryFingerprint=digest({k:data[k] for k in ['trackGeometry','corners','elevation']}),neighborFingerprint=digest(data['spectatorZones']),facilitiesFingerprint=digest(facilities),roadIntersectionMetres2=0,otherZoneIntersections=conflicts,facilityReview={'renderedPitOverlapMetres2':0,'buildingPlanOverlapMetres2':0},evidence=dict(annualPage={**opening,'sha256':hashlib.sha256(raw).hexdigest(),'capturedAt':'2026-01-14T01:15:54Z','ticketName':'Gold 7 Bis : Source (Weekend) - Uncovered','ticketId':'526'},panorama=dict(page='https://www.spagrandprix.com/en/gold-7-bis',url=photo_url,pageSha256=hashlib.sha256(page).hexdigest(),sha256=hashlib.sha256(photo).hexdigest(),dimensions=[8192,4096],reviewedVisually=True,captureDateVerified=False,shipped=False),excludedConflict=dict(url='https://hospitalityf1.com/en/packages/sunday-vip-pass-for-the-2026-belgian-f1-grand-prix-source-of-gold-7-bis/',claim='Covered Gold7bis grandstand seat',resolution='Prefer the explicit, dated organizer Uncovered product name; retain this conflict rather than invent a roof.')),limits='Independent approximate Bis model, not part of Gold7/Gold8 or Ter. Annual uncovered status documented; seat/railing heights and footprint precision remain estimated. No full aisle or seat reconstruction.')
zone['surfaces'][0]['rowStrip']={'front':front,'back':[boundary[i] for i in [1,0]],'source':profile}
zone['surfaces'][0]['rowBearing']='local-normal'
target.write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n','utf8');print('Prepared independently associated Bis footprint; explicit2026 uncovered status, zero current plane conflicts.')
